set-variable.value:
@{
      try {
          var body = context.Request.Body?.As<JObject>(preserveContent: true);
          if (body == null) { return "Request body must be a JSON object."; }
          if (body["messages"] == null || body["messages"].Type != JTokenType.Array || !body["messages"].HasValues) { return "Field 'messages' must be a non-empty array."; }
          var allowed = new HashSet<string> { "model", "messages", "max_tokens", "max_completion_tokens", "temperature", "top_p", "stream", "stop", "user", "demo" };
          foreach (var prop in body.Properties()) { if (!allowed.Contains(prop.Name)) { return $"Unsupported field: '{prop.Name}'."; } }
          return string.Empty;
      } catch (Exception ex) { return "Invalid JSON body: " + ex.Message; }
  }
